// Ordem em que são "desenhadas": corpo -> furo oval -> anel -> furo do anel.
const STROKES = [
  { d: BODY, anim: "logoloader-draw-body" },
  { d: OVAL_HOLE, anim: "logoloader-draw-oval" },
  { d: RING, anim: "logoloader-draw-ring" },
  { d: RING_HOLE, anim: "logoloader-draw-hole" },
];

// Ciclo único de 4s, todas as animações sincronizadas (loop sem pulos):
//  0–55%   corpo se traça
//  50–70%  furo oval
//  66–84%  anel
//  80–90%  furo do anel
//  86–95%  preenchimento aparece com fade
//  95–100% tudo some e recomeça em branco
const CSS = `
.logoloader-stroke { stroke-dasharray: 1; stroke-dashoffset: 1; opacity: 0; }
.logoloader-fill { opacity: 0; }

@keyframes logoloader-draw-body {
  0% { stroke-dashoffset: 1; opacity: 1; }
  55%, 94% { stroke-dashoffset: 0; opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 0; }
}
@keyframes logoloader-draw-oval {
  0%, 50% { stroke-dashoffset: 1; opacity: 1; }
  70%, 94% { stroke-dashoffset: 0; opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 0; }
}
@keyframes logoloader-draw-ring {
  0%, 66% { stroke-dashoffset: 1; opacity: 1; }
  84%, 94% { stroke-dashoffset: 0; opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 0; }
}
@keyframes logoloader-draw-hole {
  0%, 80% { stroke-dashoffset: 1; opacity: 1; }
  90%, 94% { stroke-dashoffset: 0; opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 0; }
}
@keyframes logoloader-fill {
  0%, 86% { opacity: 0; }
  95% { opacity: 1; }
  97% { opacity: 1; }
  100% { opacity: 0; }
}

.logoloader-stroke { animation-duration: 2s; animation-timing-function: ease-in-out; animation-iteration-count: infinite; }
.logoloader-fill { animation: logoloader-fill 4s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .logoloader-stroke { animation: none; opacity: 0; }
  .logoloader-fill { animation: none; opacity: 1; }
}
`;

/**
 * LogoLoader — logo da Trapeza "desenhada à mão": começa tudo em branco,
 * o contorno vai aparecendo de um ponto ao outro, forma por forma, e no fim
 * o preenchimento surge com fade. Em loop.
 *
 *   <LogoLoader />
 *   <LogoLoader size={64} />
 *   <LogoLoader className="text-white" />   // cor via brown
 */
export function LogoLoader({
  size = 40,
  className,
}: {
  size?: number;
  className?: string;
}) {
  return (
    <svg
      viewBox="0 0 139.34384 164.90338"
      width={size}
      height={(size * 164.90338) / 139.34384}
      className={cn("logoloader shrink-0", className)}
      role="status"
      aria-label="Carregando"
    >
      <style>{CSS}</style>
      <g transform="translate(-36.534608,-68.20399)">
        {/* preenchimento (evenodd mantém os furos) */}
        <path
          d={[BODY, OVAL_HOLE, RING, RING_HOLE].join(" ")}
          fillRule="evenodd"
          className="logoloader-fill"
          fill="brown"
        />
        {/* contornos sendo desenhados */}
        {STROKES.map(({ d, anim }) => (
          <path
            key={anim}
            d={d}
            pathLength={1}
            className="logoloader-stroke"
            style={{ animationName: anim }}
            fill="none"
            stroke="brown"
            strokeWidth={1.5}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        ))}
      </g>
    </svg>
  );
}